library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_10_vhdl is	port (x, y, clock, reset_b: in Std_Logic);end Prob_8_10_vhdl;architecture Behavioral of Prob_8_10_vhdl is	type State_type is (s0, s1, s2, s3);	signal state, next_state: State_type;begin	process (clock, reset_b) begin		if (reset_b = '0') then state <= s0; 		elsif clock'event and clock = '1' then state <= next_state;		end if;	end process;  process (state, x, y) begin    next_state <= s0;    case (state) is      when s0 =>	if (x = '0') then next_state <= s0; else next_state <= s1; end if;      when s1 =>	if (y = '0') then next_state <= s2; else next_state <= s3; end if;      when s2 =>	if (x = '0') then next_state <= s0; 						elsif (y = '0') then next_state <= s2; 						else next_state <= s3; end if;      when s3 =>	if (x = '0') then next_state <= s0; elsif (y = '0') then next_state <= s2; else next_state <= s3; end if;    end case;  end process;end Behavioral;